<?php require __DIR__.'/auth.php'; require_login(); page_start('Ghi chú','note'); ?><main class="page"><div class="eyebrow">Ghi chú cá nhân</div><h1>Ghi lại điều quan trọng</h1><p style="color:var(--muted)">Nội dung được lưu riêng cho tài khoản của bạn.</p><section class="card note-box"><textarea id="note" maxlength="10000" placeholder="Bắt đầu viết ghi chú của bạn..."></textarea><div class="note-actions"><span class="status" id="status">Đang tải ghi chú...</span><button class="button" id="save">Lưu ghi chú</button></div></section></main><script>const note=document.querySelector('#note'),status=document.querySelector('#status');fetch('notes.php').then(r=>r.json()).then(x=>{note.value=x.content||'';status.textContent=x.updated_at?'Đã cập nhật lần cuối: '+x.updated_at:'Chưa có ghi chú';}).catch(()=>status.textContent='Không tải được ghi chú');document.querySelector('#save').onclick=()=>{status.textContent='Đang lưu...';fetch('notes.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:note.value})}).then(r=>r.json()).then(x=>{status.textContent=x.ok?'Đã lưu thành công':'Lưu thất bại';}).catch(()=>status.textContent='Lưu thất bại');};</script><?php page_end(); ?>